function renderPolicySwitch(id, label, checked) {
  return `<div class="field"><div class="switch-field-row"><span class="field-label">${esc(label)}</span><ha-switch id="${id}" aria-label="${esc(label)}" ${checked ? "checked" : ""}></ha-switch></div></div>`;
}

function renderException(exception, index, t) {
  const type = exception.selector_type ?? "pack";
  const reminderMode = Object.hasOwn(exception, "reminder_interval")
    ? (exception.reminder_interval === null ? "never" : "custom")
    : "inherit";
  return `<ha-card outlined class="notification-exception" data-notification-exception="${index}">
    <div class="notification-exception-heading"><strong>${esc(t("notifications.exception_number", { count: index + 1 }))}</strong><ha-button type="button" appearance="plain" variant="danger" data-action="remove-notification-exception" data-index="${index}">${esc(t("buttons.delete"))}</ha-button></div>
    <div class="notification-exception-grid">
      <div class="field"><span class="field-label">${esc(t("notifications.selector_type"))}</span><ha-select id="notification-exception-type-${index}"></ha-select></div>
      <div class="field"><span class="field-label">${esc(t("notifications.selector"))}</span>${renderSelectorControl(type, index)}</div>
      ${renderOverrideSelect(`notification-exception-start-${index}`, t("notifications.on_start"), booleanOverrideValue(exception, "notify_on_start"))}
      ${renderOverrideSelect(`notification-exception-resolved-${index}`, t("notifications.on_resolved"), booleanOverrideValue(exception, "notify_on_resolved"))}
      <div class="field notification-exception-reminder ${reminderMode === "custom" ? "has-custom-value" : ""}"><span class="field-label">${esc(t("notifications.reminder"))}</span><div class="notification-exception-reminder-controls"><ha-select id="notification-exception-reminder-mode-${index}"></ha-select>${reminderMode === "custom" ? `<ha-input id="notification-exception-reminder-${index}" type="number" min="${MIN_NOTIFICATION_REMINDER_SECONDS}" max="${MAX_DURATION_SECONDS}" step="1" value="${esc(exception.reminder_interval)}" required aria-label="${esc(t("notifications.reminder"))}"><span slot="end">${esc(t("units.seconds"))}</span></ha-input>` : ""}</div></div>
    </div>
  </ha-card>`;
}

function renderSelectorControl(type, index) {
  if (type === "label") {
    return `<ha-selector id="notification-exception-selector-${index}"></ha-selector>`;
  }
  return `<ha-select id="notification-exception-selector-${index}"></ha-select>`;
}

function renderOverrideSelect(id, label, value) {
  return `<div class="field"><span class="field-label">${esc(label)}</span><ha-select id="${id}" data-value="${esc(value)}"></ha-select></div>`;
}

function booleanOverrideValue(exception, key) {
  return Object.hasOwn(exception, key) ? String(exception[key]) : "inherit";
}

function hydrateNotificationProfileControls(panel, { packs, rules }) {
  const draft = panel._notificationProfileDraft;
  if (!draft) return;
  const notifySelector = { entity: { multiple: true, filter: { domain: "notify" } } };
  panel._configureSelector(
    "notification-targets",
    notifySelector,
    draft.targets,
    (value) => { draft.targets = panel._multipleSelectorValue(value, draft.targets); },
  );
  panel._configureSelector(
    "notification-labels",
    { label: { multiple: true } },
    draft.label_ids,
    (value) => { draft.label_ids = panel._multipleSelectorValue(value, draft.label_ids); },
  );
  draft.exceptions.forEach((exception, index) => {
    panel._configureSelect(
      `notification-exception-type-${index}`,
      SELECTOR_TYPES.map((value) => ({
        value,
        label: panel._t(`notifications.selector_types.${value}`),
      })),
      exception.selector_type,
      (value) => {
        captureNotificationProfileDraft(panel);
        exception.selector_type = value;
        exception.selector_id = "";
        panel._refreshSettingsConfigurationDrawer();
      },
    );
    if (exception.selector_type === "label") {
      panel._configureSelector(
        `notification-exception-selector-${index}`,
        { label: {} },
        exception.selector_id,
        (value) => { exception.selector_id = typeof value === "string" ? value : ""; },
      );
    } else {
      const options = exception.selector_type === "rule"
        ? rules.map((rule) => ({ value: rule.id, label: rule.name }))
        : packs.map((pack) => ({
          value: pack.id,
          label: panel._t(`packs.${pack.translation_key || pack.id}.name`),
        }));
      panel._configureSelect(
        `notification-exception-selector-${index}`,
        options,
        exception.selector_id,
        (value) => { exception.selector_id = value ?? ""; },
      );
    }
    for (const [suffix, key] of [["start", "notify_on_start"], ["resolved", "notify_on_resolved"]]) {
      panel._configureSelect(
        `notification-exception-${suffix}-${index}`,
        POLICY_BOOLEAN_OPTIONS.map((value) => ({
          value,
          label: panel._t(`notifications.override.${value}`),
        })),
        booleanOverrideValue(exception, key),
        (value) => setBooleanOverride(exception, key, value),
      );
    }
    const reminderMode = Object.hasOwn(exception, "reminder_interval")
      ? (exception.reminder_interval === null ? "never" : "custom")
      : "inherit";
    panel._configureSelect(
      `notification-exception-reminder-mode-${index}`,
      ["inherit", "never", "custom"].map((value) => ({
        value,
        label: panel._t(`notifications.reminder_modes.${value}`),
      })),
      reminderMode,
      (value) => {
        captureNotificationProfileDraft(panel);
        if (value === "inherit") delete exception.reminder_interval;
        else if (value === "never") exception.reminder_interval = null;
        else exception.reminder_interval = DEFAULT_NOTIFICATION_REMINDER_SECONDS;
        panel._refreshSettingsConfigurationDrawer();
      },
    );
  });
}

function setBooleanOverride(exception, key, value) {
  if (value === "inherit") delete exception[key];
  else exception[key] = value === "true";
}

function captureNotificationProfileDraft(panel) {
  const draft = panel._notificationProfileDraft;
  if (!draft) return;
  draft.name = String(panel.shadowRoot.querySelector("#notification-profile-name")?.value ?? draft.name).trim();
  draft.enabled = Boolean(panel.shadowRoot.querySelector("#notification-profile-enabled")?.checked);
  draft.default_policy.notify_on_start = Boolean(panel.shadowRoot.querySelector("#notification-start")?.checked);
  draft.default_policy.notify_on_resolved = Boolean(panel.shadowRoot.querySelector("#notification-resolved")?.checked);
  const reminder = String(panel.shadowRoot.querySelector("#notification-reminder")?.value ?? "").trim();
  draft.default_policy.reminder_interval = reminder === "" ? null : Number(reminder);
  draft.exceptions.forEach((exception, index) => {
    if (!Object.hasOwn(exception, "reminder_interval") || exception.reminder_interval === null) return;
    const value = panel.shadowRoot.querySelector(`#notification-exception-reminder-${index}`)?.value;
    if (value !== undefined) exception.reminder_interval = Number(value);
  });
}

function notificationProfileValidationError(draft, t) {
  if (!draft.name) return t("notifications.validation.name");
  if (!draft.targets.length) return t("notifications.validation.targets");
  const reminder = draft.default_policy.reminder_interval;
  if (invalidReminder(reminder)) {
    return t("notifications.validation.reminder");
  }
  for (const exception of draft.exceptions) {
    if (!exception.selector_id) return t("notifications.validation.selector");
    const fields = ["notify_on_start", "notify_on_resolved", "reminder_interval"];
    if (!fields.some((field) => Object.hasOwn(exception, field))) {
      return t("notifications.validation.override");
    }
    if (Object.hasOwn(exception, "reminder_interval")
      && invalidReminder(exception.reminder_interval)) {
      return t("notifications.validation.reminder");
    }
  }
  return null;
}

function invalidReminder(value) {
  return value !== null && (
    !Number.isInteger(value) || value < MIN_NOTIFICATION_REMINDER_SECONDS
  );
}

async function saveNotificationProfiles(panel, candidateProfiles) {
  const profiles = candidateProfiles.map(cloneNotificationProfile);
  panel._busy = true;
  panel._notice = null;
  panel._refreshUiState();
  let saved = false;
  try {
    panel._config = await panel._api.call({
      type: "alert_manager/config/update",
      config: { notification_profiles: profiles },
    });
    panel._settingsDraft.notification_profiles = (
      panel._config.notification_profiles ?? []
    ).map(cloneNotificationProfile);
    panel._notificationProfileDraft = null;
    panel._notificationProfileId = null;
    panel._configurationDrawer = null;
    panel._notice = { kind: "success", text: panel._t("success.settings_saved") };
    saved = true;
  } catch (error) {
    panel._notice = null;
    panel._notificationProfileValidationError = panel._errorText(error);
  } finally {
    panel._busy = false;
    if (saved) panel._render();
    else panel._refreshSettingsConfigurationDrawer();
  }
}

function openNotificationProfile(panel, profile = null) {
  panel._notificationProfileDraft = profile
    ? cloneNotificationProfile(profile)
    : newNotificationProfileDraft();
  panel._notificationProfileId = profile?.id ?? null;
  panel._notificationProfileValidationError = null;
  panel._configurationDrawer = { kind: "notification" };
  panel._refreshSettingsConfigurationDrawer();
}

async function handleNotificationProfileAction(action, button) {
  if (action === "new-notification-profile") {
    this._ensureSettingsDraft();
    openNotificationProfile(this);
    return true;
  }
  if (action === "edit-notification-profile") {
    this._ensureSettingsDraft();
    const profile = this._settingsDraft.notification_profiles.find(
      (item) => item.id === button.dataset.profileId,
    );
    if (profile) openNotificationProfile(this, profile);
    return true;
  }
  if (action === "save-notification-profile") {
    captureNotificationProfileDraft(this);
    const error = notificationProfileValidationError(
      this._notificationProfileDraft,
      (key) => this._t(key),
    );
    if (error) {
      this._notificationProfileValidationError = error;
      this._refreshSettingsConfigurationDrawer();
      return true;
    }
    this._notificationProfileValidationError = null;
    const profile = cloneNotificationProfile(this._notificationProfileDraft);
    const profiles = (this._settingsDraft.notification_profiles ?? []).map(
      cloneNotificationProfile,
    );
    const index = profiles.findIndex((item) => item.id === this._notificationProfileId);
    if (index < 0) profiles.push(profile);
    else profiles[index] = profile;
    await saveNotificationProfiles(this, profiles);
    return true;
  }
  if (action === "delete-notification-profile") {
    this._ensureSettingsDraft();
    const profile = this._settingsDraft.notification_profiles.find(
      (item) => item.id === button.dataset.profileId,
    );
    if (!profile || !window.confirm(
      this._t("notifications.delete_confirm", { name: profile.name }),
    )) return true;
    await saveNotificationProfiles(
      this,
      this._settingsDraft.notification_profiles.filter(
        (item) => item.id !== profile.id,
      ),
    );
    return true;
  }
  if (action === "test-notification-profile") {
    const result = await this._call({
      type: "alert_manager/notifications/test",
      profile_id: button.dataset.profileId,
    }, "");
    if (!result) return true;
    const failed = (result.failed_targets ?? []).map(
      (item) => item.entity_id,
    ).join(", ");
    this._notice = result.success
      ? { kind: "success", text: this._t("notifications.test_success") }
      : {
        kind: "error",
        text: this._t("notifications.test_failed", { targets: failed }),
      };
    this._refreshUiState();
    return true;
  }
  if (action === "add-notification-exception") {
    captureNotificationProfileDraft(this);
    this._notificationProfileDraft.exceptions.push({
      selector_type: "pack",
      selector_id: "",
    });
    this._refreshSettingsConfigurationDrawer();
    return true;
  }
  if (action === "remove-notification-exception") {
    captureNotificationProfileDraft(this);
    this._notificationProfileDraft.exceptions.splice(Number(button.dataset.index), 1);
    this._refreshSettingsConfigurationDrawer();
    return true;
  }
  if (
    action === "close-configuration-drawer"
    && this._configurationDrawer?.kind === "notification"
  ) {
    this._configurationDrawer = null;
    this._notificationProfileDraft = null;
    this._notificationProfileId = null;
    this._notificationProfileValidationError = null;
    this._refreshSettingsConfigurationDrawer();
    return true;
  }
  return false;
}

// Source: frontend-src/components/rule-editor.js
function consumeRuleEditorNotice(panel, fallback) {
    const message = panel._notice?.text ?? fallback;
    panel._notice = null;
    panel._refreshUiState();
    return message;
}

function normalizeRuleDraft(rule = {}) {
    const defaults = newRuleDefaults();
    const normalized = {
      ...defaults,
      ...rule,
      entity_ids: [...(rule.entity_ids ?? defaults.entity_ids)],
    };
    if (normalized.source === "none") normalized.source = "jinja";
    if (normalized.source === "variation") normalized.source = "state_variation";
    if (VARIATION_RULE_SOURCES.has(normalized.source)
      && !VARIATION_RULE_OPERATORS.has(normalized.operator)) {
      normalized.operator = "above";
    }
    if (TEXT_RULE_OPERATORS.has(normalized.operator)) {
      normalized.value = ruleValueList(normalized.value);
    } else if (RANGE_RULE_OPERATORS.has(normalized.operator)) {
      const bounds = ruleValueList(normalized.value);
      normalized.value = [bounds[0] ?? "", bounds[1] ?? ""];
    } else {
      normalized.value = normalized.operator === "unchanged"
        ? ""
        : ruleValueList(normalized.value)[0] ?? "";
    }
    return normalized;
}

function formField(form, name) {
    return form.querySelector?.(`[data-field="${name}"]`)
      ?? form.elements?.namedItem?.(name)
      ?? form.querySelector?.(`[name="${name}"]`);
}

function captureRuleDraftFromForm(form, currentRule = {}, selectorValues = {}) {
    const value = (name) => formField(form, name)?.value;
    const optionalNumber = (name) => {
      const raw = value(name);
      return raw === undefined
        ? currentRule[name] ?? null
        : raw === "" ? null : Number(raw);
    };
    const source = value("source") ?? currentRule.source ?? "state";
    const comparisonFree = ["jinja", "unchanged"].includes(source);
    const selectedOperator = value("operator") ?? currentRule.operator ?? "equals";
    const operator = comparisonFree ? "equals" : selectedOperator;
    const valueInputs = Array.from(form.querySelectorAll?.("[data-rule-value-index]") ?? []);
    let ruleValue;
    if (comparisonFree || operator === "unchanged") {
      ruleValue = "";
    } else if (valueInputs.length) {
      ruleValue = valueInputs.map((input) => String(input.value));
    } else if (RANGE_RULE_OPERATORS.has(operator)) {
      const currentBounds = ruleValueList(currentRule.value);
      ruleValue = [
        String(value("lower-bound") ?? currentBounds[0] ?? ""),
        String(value("upper-bound") ?? currentBounds[1] ?? ""),
      ];
    } else if (TEXT_RULE_OPERATORS.has(operator)) {
      ruleValue = ruleValueList(value("value") ?? currentRule.value)
        .map((item) => String(item));
    } else {
      ruleValue = String(value("value") ?? currentRule.value ?? "");
    }
    const selectorEntityIds = selectorValues.entityIds;
    const entityIds = Array.isArray(selectorEntityIds)
      && selectorEntityIds.length === 0
      && currentRule.entity_ids?.length
      ? currentRule.entity_ids
      : selectorEntityIds ?? currentRule.entity_ids ?? [];
    return {
      ...currentRule,
      name: String(value("name") ?? currentRule.name ?? ""),
      entity_ids: Array.isArray(entityIds) ? [...entityIds] : [String(entityIds)],
      enabled: Boolean(currentRule.enabled ?? true),
      source,
      attribute: String(value("attribute") ?? currentRule.attribute ?? ""),
      operator,
      value: ruleValue,
      duration: Number(value("duration") ?? currentRule.duration ?? 900),
      message: String(selectorValues.message || currentRule.message || ""),
      update_message_when_active: Boolean(
        form.querySelector?.("#rule-update-message-when-active")?.checked
          ?? form.elements?.namedItem?.("update_message_when_active")?.checked
          ?? currentRule.update_message_when_active
          ?? false
      ),
      condition_template: String(
        selectorValues.conditionTemplate || currentRule.condition_template || "",
      ),
      flapping_enabled: Boolean(
        form.querySelector?.("#rule-flapping-enabled")?.checked
          ?? currentRule.flapping_enabled
          ?? false
      ),
      flapping_occurrences: optionalNumber("flapping_occurrences"),
      flapping_window: optionalNumber("flapping_window"),
      flapping_recovery: optionalNumber("flapping_recovery"),
    };
}

function serializeRuleDraft(draft) {
    const source = draft.source;
    const comparisonFree = ["jinja", "unchanged"].includes(source);
    const operator = comparisonFree ? "equals" : draft.operator;
    const comparisonValue = comparisonFree || operator === "unchanged"
      ? ""
      : RANGE_RULE_OPERATORS.has(operator)
      ? ruleValueList(draft.value).slice(0, 2).map((item) => String(item))
      : TEXT_RULE_OPERATORS.has(operator)
      ? ruleValueList(draft.value).map((item) => item.trim())
      : String(draft.value ?? "");
    return {
      name: String(draft.name ?? "").trim(),
      entity_ids: [...(draft.entity_ids ?? [])],
      enabled: Boolean(draft.enabled ?? true),
      source,
      attribute: ATTRIBUTE_RULE_SOURCES.has(source)
        ? String(draft.attribute ?? "").trim()
        : null,
      operator,
      value: comparisonValue,
      duration: Number(draft.duration),
      message: String(draft.message ?? "").trim() || null,
      update_message_when_active: Boolean(draft.update_message_when_active),
      condition_template: String(draft.condition_template ?? "").trim() || null,
      flapping_enabled: Boolean(draft.flapping_enabled),
      flapping_occurrences: draft.flapping_occurrences ?? null,
      flapping_window: draft.flapping_window ?? null,
      flapping_recovery: draft.flapping_recovery ?? null,
    };
}

function validateRuleDraft(draft) {
    const conditionTemplate = String(draft.condition_template ?? "").trim();
    if (conditionTemplate || (draft.source !== "jinja"
      && !VARIATION_RULE_SOURCES.has(draft.source))) {
      return { valid: true, errorKey: null };
    }
    return {
      valid: false,
      errorKey: VARIATION_RULE_SOURCES.has(draft.source)
        ? "rules.condition_template_variation_required"
        : "rules.condition_template_required",
    };
}

function refreshRuleEditor() {
    const layout = this.shadowRoot?.querySelector(".rules-layout");
    if (!layout || this._activeTab !== "rules") {
      this._render();
      return;
    }
    layout.querySelectorAll(".rule-editor-backdrop,.rule-editor-drawer,.side-drawer-bottom-sheet").forEach((node) => node.remove());
    layout.classList.toggle("has-editor", this._editingRule !== null);
    layout.style.setProperty("--rule-editor-width", `${this._ruleEditorWidth}px`);
    if (this._editingRule !== null) {
      layout.insertAdjacentHTML("beforeend", this._renderRuleEditor());
    }
    this._hydrateSelectors();
    this._hydrateYamlEditor();
    this._syncRuleTableEditingHighlight();
}

function refreshRuleConditionSection() {
    const section = this.shadowRoot?.querySelector?.("[data-rule-condition-section]");
    if (!section) {
      this._refreshRuleEditor();
      return;
    }
    section.outerHTML = renderRuleConditionSection({
      rule: normalizeRuleDraft(this._editingRule ?? {}),
      t: (key, replacements) => this._t(key, replacements),
    });
    this._hydrateRuleEditorControls();
}

function clearRuleEditorError() {
    this._ruleEditorError = null;
    this.shadowRoot?.querySelector?.(".rule-editor-error")?.remove?.();
}

function ruleTestValue(value, unit = null) {
    if (value === null || value === undefined) return null;
    const rendered = typeof value === "object" ? JSON.stringify(value) : String(value);
    return unit ? `${rendered} ${unit}` : rendered;
}

function ruleTestBoolean(value, t) {
    if (value === null || value === undefined) return null;
    return t(value ? "rules.test.true" : "rules.test.false");
}

function ruleTestDetail(label, value) {
    if (value === null || value === undefined || value === "") return "";
    return `<div class="alert-details-item"><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`;
}

function ruleTestReason(result, t) {
    if (!result.reason) return "";
    const detail = result.error_detail ? ` (${result.error_detail})` : "";
    return `${t(`rules.test.reasons.${result.reason}`)}${detail}`;
}

function ruleTestCondition(result, t) {
    if (!result.operator) return null;
    const expected = ruleTestValue(result.comparison_value);
    return expected === null
      ? t(`operators.${result.operator}`)
      : `${t(`operators.${result.operator}`)} ${expected}`;
}

function ruleTestConclusion(result, t, formatDuration) {
    if (result.status === "error") return t("rules.test.conclusion_error");
    if (result.status === "indeterminate") {
      return t("rules.test.conclusion_indeterminate");
    }
    if (result.status === "no_match") return t("rules.test.conclusion_no_match");
    return Number(result.duration) === 0
      ? t("rules.test.conclusion_immediate")
      : t("rules.test.conclusion_pending", {
        duration: formatDuration(result.duration),
      });
}

function renderRuleTestResult(result, context) {
    if (!result) return "";
    const { t, formatDuration } = context;
    if (result.request_error) {
      return `<ha-alert class="rule-test-summary" alert-type="error" role="alert"><strong>${esc(t("rules.test.title_error"))}</strong><div>${esc(result.request_error)}</div></ha-alert>`;
    }
    const alertType = result.error_count === result.total
      ? "error"
      : result.indeterminate_count > 0 || result.error_count > 0
      ? "warning"
      : result.matched_count > 0 ? "success" : "info";
    const summary = t("rules.test.summary", {
      matched: result.matched_count,
      total: result.total,
    });
    const notices = [
      result.indeterminate_count
        ? t("rules.test.summary_indeterminate", { count: result.indeterminate_count })
        : "",
      result.error_count
        ? t("rules.test.summary_errors", { count: result.error_count })
        : "",
      result.enabled === false ? t("rules.test.disabled_notice") : "",
    ].filter(Boolean);
    const items = (result.results ?? []).map((item) => {
      const variation = VARIATION_RULE_SOURCES.has(item.source);
      const statusIcon = item.status === "match"
        ? "mdi:check-circle"
        : item.status === "no_match"
        ? "mdi:close-circle-outline"
        : item.status === "indeterminate"
        ? "mdi:help-circle-outline"
        : "mdi:alert-circle";
      const statusLabel = t(`rules.test.status_${item.status}`);
      const reason = ruleTestReason(item, t);
      const unchanged = item.unchanged_seconds === null
        || item.unchanged_seconds === undefined
        ? null
        : t("rules.test.unchanged_elapsed", {
          duration: formatDuration(item.unchanged_seconds),
        });
      const messageError = item.message_error
        ? t("rules.test.message_error", { error: item.message_error })
        : null;
      return `<ha-expansion-panel outlined class="rule-test-entity">
        <div slot="header" class="rule-test-entity-header"><ha-icon icon="${statusIcon}"></ha-icon><code>${esc(item.entity_id)}</code><span>${esc(statusLabel)}</span></div>
        <div class="rule-test-details">
          <dl class="alert-details-list">
          ${ruleTestDetail(t("rules.test.entity"), item.name)}
          ${ruleTestDetail(t("rules.test.source"), t(`rules.source_${item.source}`))}
          ${ruleTestDetail(t("rules.test.attribute"), item.attribute)}
          ${ruleTestDetail(t("rules.test.current_state"), ruleTestValue(item.state, item.source === "state" ? item.unit : null))}
          ${variation ? "" : ruleTestDetail(t("rules.test.extracted_value"), ruleTestValue(item.raw_value ?? item.value, item.source !== "jinja" ? item.unit : null))}
          ${ruleTestDetail(t("rules.test.condition"), ruleTestCondition(item, t))}
          ${ruleTestDetail(t("rules.test.comparison_result"), ruleTestBoolean(item.comparison_result, t))}
          ${ruleTestDetail(t("rules.test.jinja_result"), ruleTestBoolean(item.jinja_result, t))}
          ${ruleTestDetail(t("rules.test.baseline"), ruleTestValue(item.baseline, item.unit))}
          ${ruleTestDetail(t("rules.test.current_value"), ruleTestValue(item.current_value, item.unit))}
          ${ruleTestDetail(t("rules.test.variation"), ruleTestValue(item.variation, item.unit))}
          ${ruleTestDetail(t("rules.test.unchanged"), unchanged)}
          ${ruleTestDetail(t("rules.test.duration_reached"), ruleTestBoolean(item.duration_reached, t))}
          ${ruleTestDetail(t("rules.test.final_result"), ruleTestBoolean(item.final_result, t))}
          ${ruleTestDetail(t("rules.test.delay"), formatDuration(item.duration))}
          ${ruleTestDetail(t("rules.test.reason"), reason)}
          </dl>
          ${item.message ? `<ha-alert class="rule-test-message" alert-type="info"><strong>${esc(t("rules.test.generated_message"))}</strong><div>${esc(item.message)}</div></ha-alert>` : ""}
          ${messageError ? `<ha-alert class="rule-test-message" alert-type="error">${esc(messageError)}</ha-alert>` : ""}
          <p class="rule-test-conclusion">${esc(ruleTestConclusion(item, t, formatDuration))}</p>
        </div>
      </ha-expansion-panel>`;
    }).join("");
    return `<ha-alert class="rule-test-summary" alert-type="${alertType}" role="status"><strong>${esc(t("rules.test.title"))}</strong><div>${esc(summary)}</div>${notices.map((notice) => `<div>${esc(notice)}</div>`).join("")}</ha-alert><div class="rule-test-entities">${items}</div>`;
}

function renderRuleTestResultPanel(result = this._ruleTestResult) {
    return renderRuleTestResult(result, {
      t: (key, replacements) => this._t(key, replacements),
      formatDuration: (value) => this._durationText(value),
    });
}

function updateRuleTestDisplay({ scroll = false } = {}) {
    const result = this.shadowRoot?.querySelector?.("[data-rule-test-result]");
    if (result) result.innerHTML = this._renderRuleTestResult();
    const button = this.shadowRoot?.querySelector?.('[data-action="test-rule"]');
    if (button) {
      button.disabled = Boolean(this._ruleTestLoading);
      button.loading = Boolean(this._ruleTestLoading);
      button.toggleAttribute?.("loading", Boolean(this._ruleTestLoading));
    }
    if (!scroll) return;
    const form = this.shadowRoot?.querySelector?.("#rule-form");
    if (typeof form?.scrollTo === "function") {
      form.scrollTo({ top: 0, behavior: "smooth" });
    } else if (form) form.scrollTop = 0;
}

function clearRuleTestResult() {
    if (!this._ruleTestLoading && this._ruleTestResult === null) return;
    this._ruleTestSequence += 1;
    this._ruleTestLoading = false;
    this._ruleTestResult = null;
    this._updateRuleTestDisplay();
}

function ruleAttributeOptions() {
    const attributes = new Set();
    for (const entityId of this._editingRule?.entity_ids ?? []) {
      const stateAttributes = this._hass?.states?.[entityId]?.attributes;
      if (!stateAttributes || typeof stateAttributes !== "object") continue;
      for (const attribute of Object.keys(stateAttributes)) attributes.add(attribute);
    }
    return [...attributes].sort();
}

function refreshRuleAttributeSelector() {
    const element = this.shadowRoot?.querySelector?.("#rule-attribute");
    if (!element) return;
    element.hass = this._hass;
    element.selector = {
      select: {
        options: this._ruleAttributeOptions(),
        custom_value: true,
        mode: "dropdown",
      },
    };
    element.value = this._editingRule?.attribute ?? "";
}

function renderRuleEditor(context) {
    const {
      rule,
      mode,
      busy,
      editorError,
      yamlError,
      testResult,
      testLoading,
      t,
      duplicateLabel,
      useBottomSheet = false,
      renderTextField,
      renderNumberField,
      flappingAvailable = false,
    } = context;
    const yamlMode = mode === "yaml";
    const editorContent = yamlMode
      ? renderRuleYamlEditor({ yamlError, t })
      : renderRuleVisualEditor({
        rule, t, renderTextField, renderNumberField, flappingAvailable,
        testResult,
        renderTestResult: context.renderTestResult,
      });
    const drawer = `<ha-card outlined class="side-drawer rule-editor-drawer" role="dialog" aria-modal="false" aria-label="${esc(t(rule.id ? "rules.aria_edit_dialog" : "rules.aria_create_dialog"))}">
      <div class="rule-editor-resize" role="separator" aria-orientation="vertical" aria-label="${esc(t("rules.aria_resize"))}" tabindex="0"><div class="resize-indicator"></div></div>
      <ha-dialog-header show-border>
        <ha-icon-button id="rule-editor-close" slot="navigationIcon" data-action="cancel-rule"></ha-icon-button>
        <span slot="title">${esc(t(rule.id ? "rules.modify" : "rules.create"))}</span>
        ${rule.id ? "" : `<span slot="subtitle">${esc(t("rules.new_subtitle"))}</span>`}
        <ha-dropdown slot="actionItems" data-rule-editor-menu size="m" placement="bottom-end"><ha-icon-button slot="trigger" aria-label="${esc(t("rules.aria_menu"))}" title="${esc(t("rules.aria_menu"))}"><ha-svg-icon path="${MDI_DOTS_VERTICAL}"></ha-svg-icon></ha-icon-button><ha-dropdown-item value="switch-editor"><ha-icon slot="icon" icon="mdi:playlist-edit"></ha-icon>${esc(t(yamlMode ? "rules.edit_visually" : "rules.edit_yaml"))}</ha-dropdown-item>${rule.id ? `<ha-dropdown-item value="duplicate-rule"><ha-icon slot="icon" icon="mdi:plus-circle-multiple-outline"></ha-icon>${esc(duplicateLabel)}</ha-dropdown-item><ha-dropdown-item value="delete-rule" variant="danger"><ha-icon slot="icon" icon="mdi:delete"></ha-icon>${esc(t("buttons.delete"))}</ha-dropdown-item>` : ""}</ha-dropdown>
      </ha-dialog-header>
      <form id="rule-form" class="side-drawer-form rule-editor-form">
        ${editorContent}
        <div class="actions side-drawer-actions rule-editor-actions">${mode === "visual" && editorError ? `<ha-alert class="rule-editor-error" alert-type="error" role="alert">${esc(editorError)}</ha-alert>` : ""}${mode === "visual" ? `<ha-button type="button" appearance="plain" data-action="test-rule" ${testLoading ? "disabled loading" : ""}>${esc(t("buttons.test"))}</ha-button>` : ""}<span class="action-spacer"></span><ha-button appearance="accent" variant="brand" data-action="save-rule" ${busy ? "disabled" : ""}>${esc(t("buttons.save"))}</ha-button></div>
      </form>
    </ha-card>`;
    return renderSideDrawer({
      drawer,
      backdropClass: "rule-editor-backdrop",
      closeAction: "cancel-rule",
      useBottomSheet,
    });
}

function renderRuleEditorPanel() {
    return renderRuleEditor({
      rule: normalizeRuleDraft(this._editingRule ?? {}),
      mode: this._ruleEditorMode,
      busy: this._busy,
      editorError: this._ruleEditorError,
      yamlError: this._ruleYamlError,
      testResult: this._ruleTestResult,
      testLoading: this._ruleTestLoading,
      t: (key, replacements) => this._t(key, replacements),
      duplicateLabel: this._duplicateRuleLabel(),
      useBottomSheet: this._useNativeBottomSheet(),
      renderTextField: (...args) => this._textField(...args),
      renderNumberField: (...args) => this._numberField(...args),
      renderTestResult: (result) => this._renderRuleTestResult(result),
      flappingAvailable: Boolean(this._config?.automatic?.flapping?.enabled),
    });
}

function renderRuleVisualEditor(context) {
    const { rule, t, renderTextField, renderNumberField, flappingAvailable = false, testResult, renderTestResult = () => "" } = context;
    return `
        <div class="rule-test-result" data-rule-test-result>${renderTestResult(testResult)}</div>
        <section class="rule-editor-section">
          <div class="rule-section-heading"><div><h3>${esc(t("rules.editor_information"))}</h3><small>${esc(t("rules.editor_information_help"))}</small></div></div>
          <div class="fields">
            ${renderTextField("name", t("rules.name"), rule.name, true, "name", "full")}
            <div class="field full"><span class="field-label">${esc(t("rules.entities"))}</span><ha-selector id="rule-entity-ids"></ha-selector><small>${esc(t("rules.entities_help"))}</small></div>
          </div>
        </section>
        ${renderRuleConditionSection({ rule, t })}
        <section class="rule-editor-section">
          <div class="rule-section-heading"><div><h3>${esc(t("rules.editor_trigger"))}</h3><small>${esc(t("rules.editor_trigger_help"))}</small></div></div>
          <div class="fields">
            ${renderNumberField("duration", t("rules.duration"), rule.duration, t("units.seconds"), 0, MAX_DURATION_SECONDS, { nameMode: "name" })}
            <div class="field full rule-message-field"><span class="field-label">${esc(t("rules.message_optional"))}</span><ha-selector id="rule-message-template"></ha-selector><small>${esc(t("rules.message_help"))}</small></div>
            <div class="field full"><div class="switch-field-row"><span class="field-label">${esc(t("rules.update_message_when_active"))}</span><ha-switch id="rule-update-message-when-active" name="update_message_when_active" aria-label="${esc(t("rules.update_message_when_active"))}" ${rule.update_message_when_active ? "checked" : ""}></ha-switch></div><small>${esc(t("rules.update_message_when_active_help"))}</small></div>
          </div>
        </section>
        ${flappingAvailable ? `<section class="rule-editor-section">
          <div class="rule-section-heading"><div><h3>${esc(t("rules.flapping_title"))}</h3><small>${esc(t("rules.flapping_help"))}</small></div></div>
          <div class="fields">
            <div class="field full"><div class="switch-field-row"><span class="field-label">${esc(t("rules.flapping_enabled"))}</span><ha-switch id="rule-flapping-enabled" aria-label="${esc(t("rules.flapping_enabled"))}" ${rule.flapping_enabled ? "checked" : ""}></ha-switch></div></div>
            <div class="fields full rule-flapping-settings" ${rule.flapping_enabled ? "" : "hidden"}>${renderNumberField("flapping_occurrences", t("automatic.fields.flapping_occurrences.label"), rule.flapping_occurrences, "", 2, 1000, { required: false, nameMode: "name", help: t("rules.flapping_inherit_help") })}${renderNumberField("flapping_window", t("automatic.fields.flapping_window.label"), rule.flapping_window, t("units.seconds"), 1, MAX_DURATION_SECONDS, { required: false, nameMode: "name", help: t("rules.flapping_inherit_help") })}${renderNumberField("flapping_recovery", t("automatic.fields.flapping_recovery.label"), rule.flapping_recovery, t("units.seconds"), 1, MAX_DURATION_SECONDS, { required: false, nameMode: "name", help: t("rules.flapping_inherit_help") })}</div>
          </div>
        </section>` : ""}`;
}

function renderRuleConditionSection({ rule, t }) {
    const jinjaOnly = rule.source === "jinja";
    const variation = VARIATION_RULE_SOURCES.has(rule.source);
    const unchanged = rule.source === "unchanged";
    const comparisonFree = jinjaOnly || unchanged;
    return `<div data-rule-condition-section><section class="rule-editor-section">
        <div class="rule-section-heading"><div><h3>${esc(t("rules.condition"))}</h3><small>${esc(t("rules.editor_condition_help"))}</small></div></div>
        <div class="fields">
          <div class="field"><span class="field-label">${esc(t("rules.source"))}</span><ha-select id="rule-source" data-field="source"></ha-select></div>
          <div class="field rule-attribute-field" ${ATTRIBUTE_RULE_SOURCES.has(rule.source) ? "" : "hidden"}><span class="field-label">${esc(t("rules.attribute_name"))}</span><ha-selector id="rule-attribute" data-field="attribute"></ha-selector><small>${esc(t(rule.source === "attribute_variation" ? "rules.attribute_variation_path_help" : "rules.attribute_path_help"))}</small></div>
          ${comparisonFree ? "" : `<div class="field full"><span class="field-label">${esc(t("rules.operator"))}</span><ha-select id="rule-operator" data-field="operator"></ha-select></div>${renderRuleValues({ rule, t })}`}
          <div class="field full rule-template-field"><span class="field-label">${esc(t(jinjaOnly ? "rules.condition_template_only" : variation ? "rules.condition_template_variation" : "rules.condition_template"))}</span><ha-selector id="rule-condition-template" ${jinjaOnly || variation ? 'required aria-required="true"' : ""}></ha-selector><small>${esc(t(jinjaOnly ? "rules.condition_template_only_help" : variation ? "rules.condition_template_variation_help" : unchanged ? "rules.condition_template_unchanged_help" : rule.operator === "unchanged" ? "rules.condition_template_selected_unchanged_help" : "rules.condition_template_help"))}</small></div>
        </div>
      </section></div>`;
}

function renderRuleYamlEditor({ yamlError, t }) {
    return `<section class="rule-editor-section yaml-rule-section">
      <div class="rule-section-heading"><div><h3>${esc(t("rules.yaml_title"))}</h3><small>${esc(t("rules.yaml_help"))}</small></div></div>
      <ha-code-editor id="rule-yaml-editor" mode="yaml" aria-label="${esc(t("rules.yaml_title"))}"></ha-code-editor>
      ${yamlError ? `<div class="yaml-error" role="alert">${esc(yamlError)}</div>` : ""}
    </section>`;
}

function renderRuleValues({ rule, t }) {
    if (rule.operator === "unchanged") return "";
    if (RANGE_RULE_OPERATORS.has(rule.operator)) {
      const bounds = ruleValueList(rule.value);
      return `<div class="field"><span class="field-label">${esc(t("rules.lower_bound"))}</span><ha-input data-field="lower-bound" type="number" step="any" value="${esc(bounds[0] ?? "")}" required aria-label="${esc(t("rules.lower_bound"))}"></ha-input></div><div class="field"><span class="field-label">${esc(t("rules.upper_bound"))}</span><ha-input data-field="upper-bound" type="number" step="any" value="${esc(bounds[1] ?? "")}" required aria-label="${esc(t("rules.upper_bound"))}"></ha-input></div>`;
    }
    if (!TEXT_RULE_OPERATORS.has(rule.operator)) {
      return `<div class="field full"><span class="field-label">${esc(t("rules.value"))}</span><ha-input data-field="value" name="value" type="number" step="any" value="${esc(rule.value)}" required aria-label="${esc(t("rules.value"))}"></ha-input></div>`;
    }
    const values = ruleValueList(rule.value);
    const multipleHint = rule.operator === "equals" || rule.operator === "contains"
      ? t("rules.multiple_any")
      : t("rules.multiple_none");
    return `<div class="field full rule-values-field"><span class="field-label">${esc(t("rules.values"))}</span><div class="rule-value-list">
      ${values.map((value, index) => `<div class="rule-value-row"><ha-input data-rule-value-index="${index}" type="text" value="${esc(value)}" required aria-label="${esc(t("rules.aria_value", { index: index + 1 }))}"></ha-input>${values.length > 1 ? `<ha-button appearance="plain" variant="danger" data-action="remove-rule-value" data-index="${index}" aria-label="${esc(t("rules.aria_remove_value", { index: index + 1 }))}">${esc(t("buttons.remove"))}</ha-button>` : ""}</div>`).join("")}
    </div><div class="rule-value-footer"><small>${esc(multipleHint)}</small><ha-button appearance="plain" data-action="add-rule-value"><ha-svg-icon slot="start" path="${MDI_PLUS}"></ha-svg-icon>${esc(t("buttons.add"))}</ha-button></div></div>`;
}

function ruleValueList(value) {
    return (Array.isArray(value) ? value : [value ?? ""]).map((item) => String(item));
}

function ruleSummary(rule) {
    if (rule.source === "jinja") return this._t("conditions.rule.jinja", { duration: "" });
    if (rule.source === "unchanged") {
      return this._t("conditions.rule.unchanged", { duration: "" });
    }
    const source = rule.source === "attribute"
      ? this._t("conditions.sources.attribute", { attribute: rule.attribute })
      : rule.source === "attribute_variation"
      ? this._t("conditions.sources.attribute_variation", { attribute: rule.attribute })
      : ["state_variation", "variation"].includes(rule.source)
      ? this._t("conditions.sources.state_variation")
      : this._t("conditions.sources.state");
    if (rule.operator === "unchanged") {
      return this._t("conditions.rule.selected_unchanged", { source, duration: "" });
    }
    const expected = this._ruleValueList(rule.value).join(" / ");
    return `${source} ${this._t(`operators.${rule.operator}`)} ${expected}`;
}

function duplicateRuleLabel() {
    return this._hass?.localize?.("ui.panel.config.automation.editor.duplicate")
      || (String(this._language).toLowerCase().startsWith("fr") ? "Dupliquer" : "Duplicate");
}

async function duplicateRuleDraft() {
    if (!this._editingRule?.id) return;
    if (this._ruleEditorMode === "yaml") {
      await this._switchRuleEditor();
      if (this._ruleEditorMode !== "visual" || !this._editingRule?.id) return;
    } else {
      this._captureRuleDraft();
    }
    const source = this._editingRule;
    const duplicate = {
      ...source,
      name: "",
      entity_ids: [...(source.entity_ids ?? [])],
      value: Array.isArray(source.value) ? [...source.value] : source.value,
    };
    delete duplicate.id;
    this._editingRule = duplicate;
    this._ruleEditorMode = "visual";
    this._ruleYaml = "";
    this._ruleYamlError = null;
    this._ruleEditorError = null;
    this._clearRuleTestResult();
    this._ruleDirty = true;
    this._refreshRuleEditor();
}

function handleRuleInput(event) {
    if (this._editingRule === null) return;
    const target = event.target;
    if (target?.closest?.("#rule-form")) {
      this._clearRuleEditorError();
      this._clearRuleTestResult();
      this._ruleDirty = true;
    }
    if (target?.id === "rule-yaml-editor") {
      this._ruleYaml = String(target.value ?? this._ruleYaml);
      this._ruleYamlError = null;
    }
}

function cancelRuleEditor() {
    if (this._ruleDirty && !window.confirm(this._t("rules.discard_confirm"))) return;
    this._editingRule = null;
    this._ruleEditorMode = "visual";
    this._ruleYaml = "";
    this._ruleYamlError = null;
    this._ruleDirty = false;
    this._clearRuleTestResult();
    this._clearRuleEditorError();
    this._refreshRuleEditor();
}

async function switchRuleEditor() {
    this._clearRuleEditorError();
    this._clearRuleTestResult();
    if (this._ruleEditorMode === "visual") {
      this._captureRuleDraft();
      this._ruleYaml = ruleToYaml(this._editingRule ?? newRuleDefaults());
      this._ruleYamlError = null;
      this._ruleEditorMode = "yaml";
      this._refreshRuleEditor();
      return;
    }
    const ruleId = this._editingRule?.id;
    const validated = await this._call(
      {
        type: "alert_manager/rules/yaml/validate",
        yaml: this._ruleYaml,
        ...(ruleId ? { rule_id: ruleId } : {}),
      },
      "",
    );
    if (!validated) {
      this._ruleYamlError = consumeRuleEditorNotice(this, this._t("rules.yaml_invalid"));
      this._refreshRuleEditor();
      return;
    }
    this._editingRule = { ...validated, ...(ruleId ? { id: ruleId } : {}) };
    this._ruleYamlError = null;
    this._ruleEditorMode = "visual";
    this._refreshRuleEditor();
}

async function saveRuleYaml() {
    const id = String(this._editingRule?.id ?? "");
    const message = id
      ? { type: "alert_manager/rules/yaml/update", rule_id: id, yaml: this._ruleYaml }
      : { type: "alert_manager/rules/yaml/create", yaml: this._ruleYaml };
    const updated = await this._call(
      message,
      this._t(id ? "success.rule_updated" : "success.rule_created"),
    );
    if (!updated) {
      this._ruleYamlError = consumeRuleEditorNotice(this, this._t("rules.yaml_invalid"));
      this._refreshRuleEditor();
      return;
    }
    this._editingRule = null;
    this._ruleEditorMode = "visual";
    this._ruleYaml = "";
    this._ruleYamlError = null;
    this._ruleDirty = false;
    this._replaceRule(updated);
}

function startRuleEditorResize(event) {
    const handle = event.target.closest?.(".rule-editor-resize");
    if (!handle || window.innerWidth <= 700) return;
    event.preventDefault();
    const drawer = this.shadowRoot.querySelector(".rule-editor-drawer");
    this._ruleEditorResize = {
      startX: event.clientX,
      startWidth: drawer?.getBoundingClientRect?.().width ?? this._ruleEditorWidth,
    };
    handle.classList?.add("is-resizing");
    document.addEventListener("pointermove", this._ruleEditorResizeMove);
    document.addEventListener("pointerup", this._ruleEditorResizeEnd);
    document.addEventListener("pointercancel", this._ruleEditorResizeEnd);
    document.body?.style.setProperty("cursor", "ew-resize");
    document.body?.style.setProperty("user-select", "none");
}

function resizeRuleEditor(event) {
    if (!this._ruleEditorResize) return;
    const delta = this._ruleEditorResize.startX - event.clientX;
    this._setRuleEditorWidth(this._ruleEditorResize.startWidth + delta);
}

function setRuleEditorWidth(width) {
    const viewportWidth = Number(window.innerWidth) || 1400;
    const maximum = Math.max(360, Math.min(800, viewportWidth - 64));
    this._ruleEditorWidth = Math.round(Math.min(maximum, Math.max(360, width)));
    this.shadowRoot.querySelector(".rules-layout")?.style.setProperty(
      "--rule-editor-width",
      `${this._ruleEditorWidth}px`,
    );
}

function stopRuleEditorResize() {
    document.removeEventListener("pointermove", this._ruleEditorResizeMove);
    document.removeEventListener("pointerup", this._ruleEditorResizeEnd);
    document.removeEventListener("pointercancel", this._ruleEditorResizeEnd);
    document.body?.style.removeProperty("cursor");
    document.body?.style.removeProperty("user-select");
    this.shadowRoot?.querySelector(".rule-editor-resize")?.classList.remove("is-resizing");
    this._ruleEditorResize = null;
}

function resetRuleEditorWidth(event) {
    if (!event.target.closest?.(".rule-editor-resize")) return;
    event.preventDefault();
    this._setRuleEditorWidth(560);
}

async function saveRule(form) {
    this._clearRuleEditorError();
    const draft = this._captureRuleDraft(form);
    if (!draft) return;
    const rule = serializeRuleDraft(draft);
    const id = String(this._editingRule?.id ?? "");
    const validation = validateRuleDraft(rule);
    if (!validation.valid) {
      this._ruleEditorError = this._t(validation.errorKey);
      this._refreshRuleEditor();
      return;
    }
    const message = id
      ? { type: "alert_manager/rules/update", rule_id: id, rule }
      : { type: "alert_manager/rules/create", rule };
    const updated = await this._call(
      message,
      this._t(id ? "success.rule_updated" : "success.rule_created"),
    );
    if (updated) {
      this._editingRule = null;
      this._ruleEditorMode = "visual";
      this._ruleDirty = false;
      this._replaceRule(updated);
    } else if (this._notice?.kind === "error") {
      this._ruleEditorError = consumeRuleEditorNotice(this, this._t("errors.unknown"));
      this._refreshRuleEditor();
    }
}

async function testRule(form) {
    this._clearRuleEditorError();
    const draft = this._captureRuleDraft(form);
    if (!draft) return;
    const rule = serializeRuleDraft(draft);
    const id = String(this._editingRule?.id ?? "");
    const validation = validateRuleDraft(rule);
    if (!validation.valid) {
      this._ruleTestResult = { request_error: this._t(validation.errorKey) };
      this._updateRuleTestDisplay({ scroll: true });
      return;
    }

    const sequence = ++this._ruleTestSequence;
    this._ruleTestResult = null;
    this._ruleTestLoading = true;
    this._updateRuleTestDisplay();
    try {
      const result = await this._api.testRule(rule, id);
      if (sequence !== this._ruleTestSequence) return;
      this._ruleTestResult = result;
    } catch (error) {
      if (sequence !== this._ruleTestSequence) return;
      this._ruleTestResult = { request_error: this._errorText(error) };
    } finally {
      if (sequence === this._ruleTestSequence) {
        this._ruleTestLoading = false;
        this._updateRuleTestDisplay({ scroll: true });
      }
    }
}

function captureRuleDraft(
  form = this.shadowRoot.querySelector?.("#rule-form"),
) {
    if (!form || this._editingRule === null) return null;
    this._editingRule = captureRuleDraftFromForm(form, this._editingRule, {
      entityIds: this.shadowRoot.querySelector("#rule-entity-ids")?.value,
      conditionTemplate: this.shadowRoot.querySelector("#rule-condition-template")?.value,
      message: this.shadowRoot.querySelector("#rule-message-template")?.value,
    });
    return this._editingRule;
}

function hydrateRuleEditor(root, context) {
  hydrateRuleEditorMenu(root, context.onMenuSelected);
  const closeButton = root?.querySelector?.("#rule-editor-close");
  if (closeButton) {
    closeButton.label = context.closeLabel;
    closeButton.path = MDI_CLOSE;
  }
  if (context.mode !== "visual") return;
  context.configureSelect(
    "rule-source",
    context.sourceOptions,
    context.draft.source ?? "state",
    context.onSourceChanged,
  );
  context.configureSelect(
    "rule-operator",
    context.operatorOptions,
    context.draft.operator ?? "equals",
    context.onOperatorChanged,
  );
  context.configureSelector(
    "rule-entity-ids",
    { entity: { multiple: true, exclude_entities: CUSTOM_RULE_EXCLUDED_ENTITY_IDS } },
    context.draft.entity_ids ?? [],
    context.onEntitiesChanged,
  );
  context.configureSelector(
    "rule-attribute",
    { select: { options: context.attributeOptions, custom_value: true, mode: "dropdown" } },
    context.draft.attribute ?? "",
    context.onAttributeChanged,
  );
  context.configureSelector(
    "rule-condition-template",
    { template: {} },
    context.draft.condition_template ?? "",
    context.onConditionTemplateChanged,
  );
  context.configureSelector(
    "rule-message-template",
    { template: {} },
    context.draft.message ?? "",
    context.onMessageChanged,
  );
  const flappingToggle = root?.querySelector?.("#rule-flapping-enabled");
  if (flappingToggle) flappingToggle.onchange = context.onFlappingChanged;
}

function hydrateRuleEditorMenu(root, onSelected) {
  const menu = root?.querySelector?.("[data-rule-editor-menu]");
  if (!menu?.addEventListener) return;
  menu._alertManagerOnSelected = onSelected;
  if (menu._alertManagerMenuConfigured) return;
  menu.addEventListener("wa-select", (event) => {
    event.stopPropagation();
    void menu._alertManagerOnSelected?.(event);
  });
  menu._alertManagerMenuConfigured = true;
}

function hydrateRuleEditorControls() {
  const variation = VARIATION_RULE_SOURCES.has(this._editingRule.source);
  hydrateRuleEditor(this.shadowRoot, {
    mode: this._ruleEditorMode,
    draft: this._editingRule,
    closeLabel: this._t("rules.aria_close"),
    sourceOptions: [
      { value: "state", label: this._t("rules.source_state") },
      { value: "attribute", label: this._t("rules.source_attribute") },
      { value: "state_variation", label: this._t("rules.source_state_variation") },
      { value: "attribute_variation", label: this._t("rules.source_attribute_variation") },
      { value: "unchanged", label: this._t("rules.source_unchanged") },
      { value: "jinja", label: this._t("rules.source_jinja") },
    ],
    operatorOptions: (variation ? [
      { value: "above", label: this._t("operators.above") },
      { value: "below", label: this._t("operators.below") },
      { value: "between", label: this._t("operators.between") },
      { value: "outside", label: this._t("operators.outside") },
    ] : [
      { value: "equals", label: this._t("operators.equals") },
      { value: "not_equals", label: this._t("operators.not_equals") },
      { value: "contains", label: this._t("operators.contains") },
      { value: "not_contains", label: this._t("operators.not_contains") },
      { value: "above", label: this._t("operators.above") },
      { value: "below", label: this._t("operators.below") },
      { value: "between", label: this._t("operators.between") },
      { value: "outside", label: this._t("operators.outside") },
      { value: "unchanged", label: this._t("operators.unchanged") },
    ]),
    attributeOptions: this._ruleAttributeOptions(),
    configureSelect: (...args) => this._configureSelect(...args),
    configureSelector: (...args) => this._configureSelector(...args),
    onMenuSelected: (event) => this._handleSelected(event),
    onSourceChanged: (value) => {
      const previousSource = this._editingRule.source ?? "state";
      this._captureRuleDraft();
      this._editingRule.source = value;
      if (!ATTRIBUTE_RULE_SOURCES.has(value)) this._editingRule.attribute = "";
      if (VARIATION_RULE_SOURCES.has(value) && !VARIATION_RULE_OPERATORS.has(this._editingRule.operator)) {
        this._editingRule.operator = "above";
        this._editingRule.value = this._ruleValueList(this._editingRule.value)[0] ?? "";
      }
      this._ruleDirty = true;
      if (["jinja", "unchanged"].includes(previousSource)
        || ["jinja", "unchanged"].includes(value)
        || VARIATION_RULE_SOURCES.has(previousSource)
        || VARIATION_RULE_SOURCES.has(value)) {
        this._refreshRuleConditionSection();
      } else {
        const attributeField = this.shadowRoot.querySelector(".rule-attribute-field");
        if (attributeField) attributeField.hidden = !ATTRIBUTE_RULE_SOURCES.has(value);
      }
    },
    onOperatorChanged: (value) => {
      this._captureRuleDraft();
      this._editingRule.operator = value;
      this._ruleDirty = true;
      if (TEXT_RULE_OPERATORS.has(value)) {
        this._editingRule.value = this._ruleValueList(this._editingRule.value);
      } else if (RANGE_RULE_OPERATORS.has(value)) {
        const bounds = this._ruleValueList(this._editingRule.value);
        this._editingRule.value = [bounds[0] ?? "", bounds[1] ?? ""];
      } else if (value === "unchanged") {
        this._editingRule.value = "";
      } else {
        this._editingRule.value = this._ruleValueList(this._editingRule.value)[0] ?? "";
      }
      this._refreshRuleConditionSection();
    },
    onEntitiesChanged: (value) => {
      this._editingRule.entity_ids = this._multipleSelectorValue(
        value,
        this._editingRule.entity_ids,
      );
      this._ruleDirty = true;
    },
    onAttributeChanged: (value) => {
      this._editingRule.attribute = String(value ?? "");
      this._ruleDirty = true;
    },
    onConditionTemplateChanged: (value) => {
      this._editingRule.condition_template = String(value ?? "");
      this._ruleDirty = true;
    },
    onMessageChanged: (value) => {
      this._editingRule.message = String(value ?? "");
      this._ruleDirty = true;
    },
    onFlappingChanged: (event) => {
      this._captureRuleDraft();
      this._editingRule.flapping_enabled = Boolean(event.target.checked);
      this._ruleDirty = true;
      const settings = this.shadowRoot.querySelector(".rule-flapping-settings");
      if (settings) settings.hidden = !this._editingRule.flapping_enabled;
    },
  });
}

// Source: frontend-src/views/overview.js
function refreshOverviewData() {
    const tablePage = this.shadowRoot?.querySelector('[data-alert-table-page="overview"]');
    if (!tablePage) {
      this._render();
      return;
    }
    const counts = {
      active: this._alerts.active_count,
      pending: this._alerts.pending_count,
      acknowledged: this._alerts.acknowledge_count ?? this._alerts.acknowledge?.length ?? 0,
      tracked: this._alerts.tracked_count ?? 0,
    };
    for (const [key, count] of Object.entries(counts)) {
      const value = tablePage.querySelector?.(`[data-summary="${key}"] strong`);
      if (value) value.textContent = String(count);
    }
    this._refreshAlertTableData("overview", tablePage);
    this._updateCountdowns();
}

function renderOverview(context) {
    const {
      alerts, selectedStatuses, pageMessages, rows,
      renderAlertTable, t,
    } = context;
    const selected = (status) => selectedStatuses.length === 1 && selectedStatuses[0] === status;
    const summary = `${pageMessages}
      <section class="summary">
        <ha-card outlined data-summary="active" data-action="filter-summary-status" data-status="active" tabindex="0" role="button" aria-pressed="${selected("active")}"><span>${esc(t("overview.summary_active"))}</span><strong class="danger">${alerts.active_count}</strong></ha-card>
        <ha-card outlined data-summary="pending" data-action="filter-summary-status" data-status="pending" tabindex="0" role="button" aria-pressed="${selected("pending")}"><span>${esc(t("overview.summary_pending"))}</span><strong class="pending">${alerts.pending_count}</strong></ha-card>
        <ha-card outlined data-summary="acknowledged" data-action="filter-summary-status" data-status="acknowledged" tabindex="0" role="button" aria-pressed="${selected("acknowledged")}"><span>${esc(t("overview.summary_acknowledged"))}</span><strong class="acknowledged">${alerts.acknowledge_count ?? alerts.acknowledge?.length ?? 0}</strong></ha-card>
        <ha-card outlined data-summary="tracked"><span>${esc(t("overview.summary_tracked"))}</span><strong>${alerts.tracked_count ?? 0}</strong></ha-card>
      </section>`;
    return renderAlertTable("overview", rows, summary);
}

function renderOverviewPanel() {
    return renderOverview({
      alerts: this._alerts,
      selectedStatuses: this._filterValues(this._tableState.overview.filters.status),
      pageMessages: this._renderPageMessages(),
      rows: this._tableRows("overview"),
      renderAlertTable: (...args) => this._renderAlertTable(...args),
      t: (key, replacements) => this._t(key, replacements),
    });
}

async function bulkAlertAction(service) {
    if (this._busy) return;
    const compatibleStatus = service === "acknowledge" ? "active" : "acknowledged";
    const rows = this._tableRows("overview").filter((row) => (
      this._selectedAlertIds.has(row.id) && row.status === compatibleStatus
    ));
    if (!rows.length) return;
    this._busy = true;
    this._notice = null;
    this._refreshUiState();
    try {
      await this._api.call({
        type: "alert_manager/alerts/acknowledgement/update",
        alert_ids: rows.map((row) => row.id),
        acknowledged: service === "acknowledge",
      });
      for (const row of rows) {
        this._applyOptimisticAcknowledgement(row.id, service === "acknowledge");
        this._selectedAlertIds.delete(row.id);
      }
      this._notice = {
        kind: "success",
        text: this._t(
          service === "acknowledge" ? "table.selection.acknowledged_result" : "table.selection.unacknowledged_result",
          { count: rows.length },
        ),
      };
    } catch (error) {
      this._notice = { kind: "error", text: this._errorText(error) };
    } finally {
      this._busy = false;
      this._refreshOverviewData();
      this._updateSelectionToolbar();
      this._refreshUiState();
    }
}

function applyOptimisticAcknowledgement(alertId, acknowledged) {
    const fromKey = acknowledged ? "alerts" : "acknowledge";
    const toKey = acknowledged ? "acknowledge" : "alerts";
    const index = (this._alerts[fromKey] ?? []).findIndex((alert) => alert.id === alertId);
    if (index < 0) return;
    const [alert] = this._alerts[fromKey].splice(index, 1);
    const updated = acknowledged
      ? {
        ...alert,
        acknowledged: true,
        acknowledged_at: new Date().toISOString(),
        acknowledged_by: this._hass?.user?.name || null,
      }
      : {
        ...alert,
        acknowledged: false,
        acknowledged_at: null,
        acknowledged_by: null,
      };
    this._alerts[toKey] = [...(this._alerts[toKey] ?? []), updated];
    this._alerts.active_count = this._alerts.alerts.length;
    this._alerts.acknowledge_count = this._alerts.acknowledge.length;
}

async function updateAlertAcknowledgement(service, alertId) {
    if (this._busy || !["acknowledge", "unacknowledge"].includes(service)) return false;
    const expectedStatus = service === "acknowledge" ? "active" : "acknowledged";
    const row = this._tableRows("overview").find((item) => item.id === alertId);
    if (!row || row.status !== expectedStatus) return false;
    this._busy = true;
    this._notice = null;
    this._refreshUiState();
    try {
      await this._hass.callService("alert_manager", service, { alert_id: alertId });
      this._applyOptimisticAcknowledgement(alertId, service === "acknowledge");
      const updatedRow = this._tableRows("overview").find((item) => item.id === alertId);
      if (this._alertDetailsDialog && updatedRow) {
        this._alertDetailsDialog.headerTitle = updatedRow.entityName || updatedRow.entityId;
        this._alertDetailsDialog.heading = updatedRow.entityName || updatedRow.entityId;
        this._alertDetailsDialog.innerHTML = this._renderAlertDetails("overview", updatedRow);
      }
      this._notice = {
        kind: "success",
        text: this._t(service === "acknowledge"
          ? "success.alert_acknowledged"
          : "success.alert_unacknowledged"),
      };
      return true;
    } catch (error) {
      this._notice = { kind: "error", text: this._errorText(error) };
      return false;
    } finally {
      this._busy = false;
      this._refreshOverviewData();
      this._refreshUiState();
    }
}

async function handleOverviewAction(action, button) {
  if (action === "bulk-acknowledge" || action === "bulk-unacknowledge") {
    await this._bulkAlertAction(action === "bulk-acknowledge" ? "acknowledge" : "unacknowledge");
    return true;
  }
  if (action === "filter-summary-status") {
    const status = button.dataset.status;
    if (!["active", "pending", "acknowledged"].includes(status)) return true;
    const selectedStatuses = this._filterValues(this._tableState.overview.filters.status);
    this._tableState.overview.filters.status = selectedStatuses.length === 1
      && selectedStatuses[0] === status
      ? []
      : [status];
    this._render();
    return true;
  }
  if (action === "enable-monitoring") {
    if (this._busy) return true;
    this._busy = true;
    this._refreshUiState();
    try {
      await this._hass.callService("switch", "turn_on", {
        entity_id: "switch.alert_manager_main_monitoring",
      });
      this._monitoringEnabled = true;
      if (this._config) this._config.monitoring_enabled = true;
    } catch (error) {
      this._notice = { kind: "error", text: this._errorText(error) };
    } finally {
      this._busy = false;
      this._refreshUiState();
    }
    return true;
  }
  return false;
}

